/bin/bash -lc "python3 - <<'PY'
import urllib.request, concurrent.futures
base='https://raw.githubusercontent.com/NVIDIA/cuda-samples/db3eea23946bca2e90a75eca2b5b3e07158a9e11/'
paths=['Samples/5_Domain_Specific/MonteCarloMultiGPU/MonteCarloMultiGPU.cpp','Samples/5_Domain_Specific/MonteCarloMultiGPU/MonteCarlo_kernel.cu','Samples/5_Domain_Specific/MonteCarloMultiGPU/CMakeLists.txt']
def read(path):
 try:
  text=urllib.request.urlopen(base+path,timeout=20).read().decode()
  return path+'\\n'+text
 except Exception as e: return path+'\\nUNAVAILABLE: '+str(e)
with concurrent.futures.ThreadPoolExecutor() as pool:
 for result in pool.map(read,paths): print(result)
PY"

